{
  "description": "Input schema for FRED series observations queries.",
  "properties": {
    "series_id": {
      "description": "The FRED series ID to fetch observations for",
      "title": "Series Id",
      "type": "string"
    },
    "start_date": {
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "description": "Start date in YYYY-MM-DD format",
      "title": "Start Date"
    },
    "end_date": {
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "description": "End date in YYYY-MM-DD format",
      "title": "End Date"
    }
  },
  "required": [
    "series_id"
  ],
  "title": "SeriesObservationsInput",
  "type": "object"
}
```

